// App.js
import React, { Suspense } from 'react';
import { fetchUsers, fetchPosts } from './api';

// Lazy load các component User và Post
const User = React.lazy(() => import('./User'));
const Post = React.lazy(() => import('./Post'));

// Hàm bọc Promise để tương thích với React Suspense
const createResource = (fetcher) => {
    let status = 'pending';
    let result;
    let suspender = fetcher().then(
        (res) => {
            status = 'success';
            result = res;
        },
        (err) => {
            status = 'error';
            result = err;
        }
    );
    return () => {
        if (status === 'pending') throw suspender;
        if (status === 'error') throw result;
        return result;
    };
};

const usersResource = createResource(fetchUsers);
const postsResource = createResource(fetchPosts);

const Exercise23 = () => {
    return (
        <div>
            <nav className="navbar navbar-dark bg-dark px-4">
                <span className="navbar-brand">Logo</span>
            </nav>

            <Suspense fallback={<div className="text-center mt-5"><h3>Loading...</h3></div>}>
                {/* Bạn có thể hiển thị riêng từng component hoặc cả hai tùy theo route */}
                <User usersPromise={usersResource} />
                <Post postsPromise={postsResource} />
            </Suspense>
        </div>
    )
}

export default Exercise23
